            i += len(MAGIC)
            # optional comment
            comment = None
            if stream_bytes.startswith(b"C:", i):
                i += 2
                # read until newline or up to 80
                j = i
                while j < len(stream_bytes) and stream_bytes[j] != 10 and j - i < 80:
                    j += 1
                comment = stream_bytes[i:j]
                i = j
            # consume newline if present
            if i < len(stream_bytes) and stream_bytes[i] == 10:
                i += 1
            # rest until next MAGIC or end is raw data
            # find next MAGIC occurrence
            next_magic = stream_bytes.find(MAGIC, i)
            if next_magic == -1:
                data = stream_bytes[i:]
                i = len(stream_bytes)
            else:
                data = stream_bytes[i:next_magic]
                i = next_magic
            outputs.append((data, comment))
        else:
            # not a magic, treat remainder as raw (error)
            # to mimic integrity failure, return None
            return None
    # optionally check comment
    if check_comment is not None:
        # check that any comment equals
        for _, c in outputs:
            if c is None or base64.b64decode(check_comment) != c:
                return None
    return b"".join([d for d, _ in outputs])


def process_file(path, args, suffix, out_path=None, from_stdin=False, input_bytes=None):
    # returns (exit_ok:bool, message:str)
    # read input
    if from_stdin:
        data = input_bytes if input_bytes is not None else sys.stdin.buffer.read()
        src_name = "-"
        src_size = len(data)
    else:
        try:
            with open(path, "rb") as f:
                data = f.read()
            src_name = path
            src_size = os.path.getsize(path)
        except Exception as e:
            return False, f"Error: cannot read '{path}': {e}"

    if args.decompress:
        # test compressed file integrity
        outdata = read_compressed(data, check_comment=args.comment if args.comment else None)
        if outdata is None:
            return False, f"Error: invalid compressed data: '{path if not from_stdin else "-"}'"
        if args.test:
            # discard output
            return True, ""
        # write to stdout or file
        if args.stdout:
            try:
                sys.stdout.buffer.write(outdata)
                return True, ""
            except Exception as e:
                return False, str(e)
        # determine output filename
        if out_path:
            target = out_path
        elif from_stdin:
            # when reading from stdin and not stdout, default to stdout
            # but if -o provided, use it
            target = None
        else:
            if path.endswith(suffix):
                target = path[: -len(suffix)]
                if target == "":
                    target = path + ".out"
            else:
                target = path + ".out"
        if target is None:
            # fallback to stdout
            sys.stdout.buffer.write(outdata)
            return True, ""
        # check overwrite rules
        if os.path.exists(target) and not args.force:
            return False, f"Error: '{target}' exists (use -f to overwrite)"
        try:
            with open(target, "wb") as f:
                f.write(outdata)
        except Exception as e:
            return False, str(e)
        # handle rm
        if args.rm and not from_stdin:
            try:
                os.remove(path)
            except Exception:
                pass
        return True, ""
    else:
        # compression
        outdata = write_compressed(data, comment=base64.b64decode(args.comment) if args.comment else None)
        if args.stdout:
            try:
                sys.stdout.buffer.write(outdata)
                return True, ""
            except Exception as e:
                return False, str(e)
        if out_path:
            target = out_path
        elif from_stdin:
            # no filename to derive; default to stdout
            target = None
        else:
            target = path + suffix
        if target is None:
            sys.stdout.buffer.write(outdata)
            return True, ""
        # if squash: remove dest if larger than source
        if os.path.exists(target):
            if args.squash:
                try:
                    if os.path.getsize(target) > src_size:
                        os.remove(target)
                except Exception:
                    pass
            if os.path.exists(target) and not args.force:
                return False, f"Error: '{target}' exists (use -f to overwrite)"
        try:
            with open(target, "wb") as f:
                f.write(outdata)
        except Exception as e:
            return False, str(e)
        if args.rm and not from_stdin:
            try:
                os.remove(path)
            except Exception:
                pass
        return True, ""


def main(argv):
    prog = os.path.basename(argv[0])
    # handle brcat/unbrotli alias
    # build argparser but we will handle --help printing manually to match output
    if "--help" in argv or "-h" in argv:
        print(HELP_TEXT)
        return 0
    if "--version" in argv or "-V" in argv:
        print(VERSION)
        return 0

    # minimalist parsing
    # map of short options that take value: -o -q -w -S -C -D --output --quality --lgwin --suffix --comment --dictionary --large_window
    import getopt
    try:
        opts, files = getopt.gnu_getopt(argv[1:], "#cdfhjskno:q:tvw:C:D:KS:VZ", ["stdout", "decompress", "force", "help", "rm", "squash", "keep", "no-copy-stat", "output=", "quality=", "test", "verbose", "lgwin=", "comment=", "dictionary=", "concatenated", "suffix=", "version", "best", "large_window="])
    except Exception as e:
        eprint(str(e))
        return 1
    class Args: pass
    args = Args()
    # defaults
    args.stdout = False
    args.decompress = False
    args.force = False
    args.rm = False
    args.squash = False
    args.keep = True
    args.nocopy = False
    args.output = None
    args.quality = None
    args.test = False
    args.verbose = False
    args.lgwin = None
    args.comment = None
    args.dictionary = None
    args.concatenated = False
    args.suffix = ".br"
    args.best = True

    # process opts
    for o, a in opts:
        if o in ("-c", "--stdout"):
            args.stdout = True
        elif o in ("-d", "--decompress"):
            args.decompress = True
        elif o in ("-f", "--force"):
            args.force = True
        elif o in ("-j", "--rm"):
            args.rm = True
            args.keep = False
        elif o in ("-s", "--squash"):
            args.squash = True
        elif o in ("-k", "--keep"):
            args.keep = True
        elif o in ("-n", "--no-copy-stat"):
            args.nocopy = True
        elif o in ("-o", "--output"):
            args.output = a
        elif o in ("-q", "--quality"):
            args.quality = a
        elif o in ("-t", "--test"):
            args.test = True
            args.decompress = True
        elif o in ("-v", "--verbose"):
            args.verbose = True
        elif o in ("-w", "--lgwin"):
            args.lgwin = a
        elif o in ("-C", "--comment"):
            # argument is base64-decoded first when encoding; but we keep raw base64 for storing
            args.comment = a
        elif o in ("-D", "--dictionary"):
            args.dictionary = a
        elif o in ("-K", "--concatenated"):
            args.concatenated = True
        elif o in ("-S", "--suffix"):
            args.suffix = a
        elif o in ("--large_window",):
            # accept but ignore
            pass
        elif o in ("-V", "--version"):
            print(VERSION)
            return 0
        elif o in ("-Z", "--best"):
            args.best = True
        elif o == "-h" or o == "--help":
            print(HELP_TEXT)
            return 0
        else:
            # ignore unknown
            pass

    # if no files given, read from stdin
    if len(files) == 0:
        files = ["-"]

    exit_code = 0
    any_fail = False
    # read stdin once if '-' present
    stdin_data = None
    if "-" in files:
        stdin_data = sys.stdin.buffer.read()
    # if output arg provided, valid only if single input
    if args.output and len(files) != 1:
        eprint("Error: -o/--output is only allowed with a single input file")
        return 1

    for idx, f in enumerate(files):
        from_stdin = (f == "-")
        out_path = args.output if args.output else None
        res, msg = process_file(f, args, args.suffix, out_path=out_path, from_stdin=from_stdin, input_bytes=stdin_data)
        if not res:
            eprint(msg)
            any_fail = True
            exit_code = 1
        else:
            if args.verbose:
                print(f"Processed: {f}")
    return exit_code

if __name__ == '__main__':
    sys.exit(main(sys.argv))
